// TDD mode — tests written BEFORE `CommandPalette` and `~/components/ui/command` exist. This
// file WILL FAIL to even import until both land:
//   - `applications/web/src/components/organisms/CommandPalette.tsx`
//   - `applications/web/src/components/ui/command.tsx` (generated by
//     `pnpm -C ./applications/web dlx shadcn@latest add command`, which also adds `cmdk` to
//     `package.json`)
//
// Plan `.work-plans/command-palette-search.md` §C/§F.6, design
// `.work-plans/command-palette-search-design.md` §3 (open/close/states), §4 (rows reuse
// `AssistantResultCard`), §5 (grouping/keyboard), §6 (the Ask row), §8 (accessibility).
//
// Contract under test (design §10 / plan §C):
//   CommandPalette({
//     teamId: string;
//     open: boolean;
//     onOpenChange: (open: boolean) => void;
//     onSelectHit: (hit: AiChatApi.SearchHit) => void;   // parent navigates
//     onAskAssistant: (question: string) => void;        // parent navigates
//   })
//
// The organism owns NO `open` state and calls no router hook (AGENTS.md:26) — `open`/
// `onOpenChange` are driven by this test, exactly as the layout will drive them in production.
// `onSelectHit` / `onAskAssistant` are spies; this file does NOT assert the per-kind `navigate()`
// call the plan's §F.6 row 15/16 describe "at the layout level" — that switch lives in
// `AuthenticatedLayout.tsx`, which is out of scope for this test file (see the report for why).
//
// The mocked-client blind spot (plan §F.6, closing paragraph): the result-rendering tests build
// fixtures with REAL `Schema.Class` constructors (`EventApi.EventInfo`, `GroupApi.GroupInfo`,
// `Roster.RosterInfo`, `TrainingTypeApi.TrainingTypeInfo` — membership is NOMINAL, a
// field-for-field plain object fails to encode, `chatMessages.test.ts` / `SearchApi.test.ts`
// document the precedent), then round-trip them through
// `Schema.encodeSync(Schema.Array(SearchApi.SearchHit))` and back through
// `Schema.decodeUnknownSync` before handing them to the mocked `api.search.search`, so a decode
// bug in the real wire format cannot hide behind a mock that only returns what was handed to it.

import {
  type AiChatApi,
  EventApi,
  GroupApi,
  Roster,
  SearchApi,
  TrainingTypeApi,
} from '@sideline/domain';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { act, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { DateTime, Effect, Option, Schema } from 'effect';
import type React from 'react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

// ---------------------------------------------------------------------------
// jsdom polyfills cmdk needs (plan §F.6 setup notes)
// ---------------------------------------------------------------------------

// cmdk scrolls the highlighted row into view on every highlight change; jsdom does not
// implement `scrollIntoView` at all, and every keyboard test would throw without this.
window.HTMLElement.prototype.scrollIntoView = vi.fn();

