// An explicit, FINITE map — never an identity fallback for the known keys. If the component
// ever computes a key (e.g. a template literal over `kind` instead of an explicit per-kind
// lookup), the computed key misses this map, falls through to the raw-key fallback below, and
// trips the "no raw search_/assistant_ key leaks into the DOM" assertion in the results test.
const TR_MAP: Record<string, string> = {
  search_title: 'Search',
  search_description: 'Search description copy',
  search_placeholder: 'Search placeholder copy',
  search_hint: 'Search hint copy',
  search_loading: 'Search loading copy',
  search_noResults: 'No matches for "{query}"',
  search_error: 'Search error copy',
  search_resultCount: '{count} results copy',
  search_askAssistant: 'Ask the assistant: "{query}"',
  search_askAssistantAbout: 'Ask the assistant about "{query}"',
  event_events: 'Events',
  team_members: 'Members',
  team_groups: 'Groups',
  team_rosters: 'Rosters',
  team_trainingTypes: 'Training Types',
  error_offline: 'You are offline',
  assistant_result_event: 'Event kind',
  assistant_result_member: 'Member kind',
  assistant_result_group: 'Group kind',
  assistant_result_roster: 'Roster kind',
  assistant_result_trainingType: 'Training type kind',
  group_memberCount: 'members count copy',
  roster_memberCount: 'roster members count copy',
  roster_active: 'On roster',
  roster_inactive: 'Off roster',
  trainingType_noGroup: 'Everyone',
  event_allDayLabel: 'Full day',
  event_status_active: 'Confirmed',
  event_status_cancelled: 'Called off',
  event_status_started: 'Underway',
  event_type_training: 'Practice',
  event_type_match: 'Match day',
  event_type_tournament: 'Tournament',
  event_type_meeting: 'Meeting',
  event_type_social: 'Social',
  event_type_other: 'Other',
};

function interpolate(template: string, params?: Record<string, unknown>): string {
  if (!params) return template;
  return template.replace(/\{(\w+)\}/g, (whole: string, key: string) =>
    params[key] === undefined ? whole : String(params[key]),
  );
}

vi.mock('~/lib/translations.js', () => ({
  tr: (key: string, params?: Record<string, unknown>) => interpolate(TR_MAP[key] ?? key, params),
  setTranslationOverrides: vi.fn(),
}));

vi.mock('~/hooks/use-mobile.js', () => ({
  useIsMobile: vi.fn(() => false),
}));

// Radix `Avatar.Image` never fires a load event in jsdom — same workaround as
// `AssistantResultCard.test.tsx` / `AssistantConversation.test.tsx`, needed here because the
// palette renders member rows through the real `AssistantResultCard`.
vi.mock('~/components/ui/avatar', () => ({
  Avatar: ({ children, ...rest }: React.PropsWithChildren<Record<string, unknown>>) => (
    <div data-slot='avatar' {...rest}>
      {children}
    </div>
  ),
  AvatarImage: (props: React.ImgHTMLAttributes<HTMLImageElement>) => (
    // biome-ignore lint/a11y/useAltText: alt is forwarded via {...props} from the real caller
    <img data-slot='avatar-image' {...props} />
  ),
  AvatarFallback: ({ children, ...rest }: React.PropsWithChildren<Record<string, unknown>>) => (
    <span data-slot='avatar-fallback' {...rest}>
      {children}
    </span>
  ),
}));

// `AssistantResultCard`'s default (non-`renderWrapper`) branch imports `Link` at module scope,
// so it must be mocked even though the palette itself never renders that branch (it always
// passes `renderWrapper`, per design §4). Self-contained (no captured outer variables — safe
// under `vi.mock` hoisting), same idiom as `AssistantResultCard.test.tsx`.
vi.mock('@tanstack/react-router', () => ({
  Link: ({
    to,
    params,
    children,
    ...rest
  }: React.PropsWithChildren<{ to: string; params?: Record<string, unknown> }>) => {
    const href = String(to).replace(/\$([a-zA-Z]+)/g, (whole: string, key: string) =>
      params && key in params ? String(params[key]) : whole,
    );
    return (
      <a href={href} {...rest}>
        {children}
      </a>
    );
  },
}));

// `mockSearch` stands in for the generated client's `api.search.search(...)` — the one call
// this organism makes (Pattern C, `applications/web/AGENTS.md:831`). `mockRun` really executes
// the piped Effect via `Effect.option` (mirrors `runPromiseClient`'s shape minus toast side
// effects), matching `AssistantConversation.test.tsx`'s precedent.
const { mockSearch } = vi.hoisted(() => ({ mockSearch: vi.fn() }));

const mockRun = () => (effect: Effect.Effect<unknown, unknown>) =>
  Effect.runPromise(Effect.option(effect));

vi.mock('~/lib/runtime', () => ({
  ApiClient: { asEffect: () => Effect.succeed({ search: { search: mockSearch } }) },
  ClientError: { make: (message: string) => ({ _tag: 'ClientError', message }) },
  SilentClientError: class SilentClientError {
    readonly _tag = 'SilentClientError';
    props: { message: string };
    constructor(props: { message: string }) {
      this.props = props;
    }
  },
  useRun: () => mockRun,
}));

// Dynamic import AFTER mocks — will fail until CommandPalette (and ui/command, and cmdk) exist.
const { CommandPalette } = await import('~/components/organisms/CommandPalette.js');

// ---------------------------------------------------------------------------
// Fixtures — real `Schema.Class` instances, mirroring `packages/domain/test/SearchApi.test.ts`.
