// The guard the plan's §F.6 closing paragraph demands: round-trip every fixture array through
// the REAL wire schema before handing it to the mock, so a decode bug cannot hide behind a mock
// that trivially returns whatever it was given.
function hitsThroughWire(
  hits: ReadonlyArray<AiChatApi.SearchHit>,
): ReadonlyArray<AiChatApi.SearchHit> {
  const encoded = Schema.encodeSync(Schema.Array(SearchApi.SearchHit))(hits);
  return Schema.decodeUnknownSync(Schema.Array(SearchApi.SearchHit))(encoded);
}

// ---------------------------------------------------------------------------
// Render helpers
// ---------------------------------------------------------------------------

interface Props {
  teamId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSelectHit: (hit: AiChatApi.SearchHit) => void;
  onAskAssistant: (question: string) => void;
}

function setup(
  overrides: Partial<Omit<Props, 'onOpenChange' | 'onSelectHit' | 'onAskAssistant'>> = {},
) {
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } });
  const onOpenChange = vi.fn();
  const onSelectHit = vi.fn();
  const onAskAssistant = vi.fn();
  const baseProps: Props = {
    teamId: TEAM_ID,
    open: true,
    onOpenChange,
    onSelectHit,
    onAskAssistant,
    ...overrides,
  };

  const utils = render(
    <QueryClientProvider client={client}>
      <CommandPalette {...baseProps} />
    </QueryClientProvider>,
  );

  const rerenderWith = (next: Partial<Props>) => {
    const merged = { ...baseProps, ...next };
    utils.rerender(
      <QueryClientProvider client={client}>
        <CommandPalette {...merged} />
      </QueryClientProvider>,
    );
  };

  return { ...utils, client, onOpenChange, onSelectHit, onAskAssistant, rerenderWith };
}

function getInput(): HTMLInputElement {
  return screen.getByRole('combobox') as HTMLInputElement;
}

async function typeQuery(value: string) {
  fireEvent.change(getInput(), { target: { value } });
}

async function settle(ms = 250) {
  await act(async () => {
    await vi.advanceTimersByTimeAsync(ms);
  });
}

beforeEach(() => {
  idCounter = 0;
  mockSearch.mockReset();
});

afterEach(() => {
  vi.useRealTimers();
  document.body.removeAttribute('data-scroll-locked');
});

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

describe('CommandPalette', () => {
  describe('hotkey (F.6/1-6)', () => {
    it('Cmd+K opens the palette', () => {
      const { onOpenChange } = setup({ open: false });
      fireEvent.keyDown(window, { key: 'k', metaKey: true });
      expect(onOpenChange).toHaveBeenCalledWith(true);
    });

    it('Ctrl+K opens the palette', () => {
      const { onOpenChange } = setup({ open: false });
      fireEvent.keyDown(window, { key: 'k', ctrlKey: true });
      expect(onOpenChange).toHaveBeenCalledWith(true);
    });

    it('a bare "k" with no modifier does nothing', () => {
      const { onOpenChange } = setup({ open: false });
      fireEvent.keyDown(window, { key: 'k' });
      expect(onOpenChange).not.toHaveBeenCalled();
    });

    it('metaKey + shiftKey does nothing (extra modifier disqualifies the chord)', () => {
      const { onOpenChange } = setup({ open: false });
      fireEvent.keyDown(window, { key: 'k', metaKey: true, shiftKey: true });
      expect(onOpenChange).not.toHaveBeenCalled();
    });

    it('does nothing while another modal owns the screen (body[data-scroll-locked]) and the palette is closed', () => {
      document.body.setAttribute('data-scroll-locked', '');
      const { onOpenChange } = setup({ open: false });
      fireEvent.keyDown(window, { key: 'k', metaKey: true });
      expect(onOpenChange).not.toHaveBeenCalled();
    });

    it('the scroll-locked guard does not block CLOSING an already-open palette', () => {
      document.body.setAttribute('data-scroll-locked', '');
      const { onOpenChange } = setup({ open: true });
      fireEvent.keyDown(window, { key: 'k', metaKey: true });
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it('Escape closes the palette (Radix Dialog default) by requesting onOpenChange(false)', () => {
      const { onOpenChange } = setup({ open: true });
      expect(screen.getByRole('dialog')).not.toBeNull();
      fireEvent.keyDown(screen.getByRole('dialog'), { key: 'Escape' });
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });
  });

  describe('states (F.6/7-10, F.6/18-19, design §6.1)', () => {
    it('below the 2-character floor: no request is issued and the hint renders, but a 1-char query still shows the Ask row', async () => {
      vi.useFakeTimers();
      setup();
      await typeQuery('a');
      await settle();

      expect(mockSearch).not.toHaveBeenCalled();
      expect(screen.getByText(TR_MAP.search_hint)).not.toBeNull();
      // "The Ask row appears at one character" (design §6.1 / plan §F.6 extra assertion #2).
      expect(
        screen.getByText(interpolate(TR_MAP.search_askAssistantAbout, { query: 'a' })),
      ).not.toBeNull();
    });

    it('an empty query shows no Ask row at all', () => {
      setup();
      expect(screen.queryByText(interpolate(TR_MAP.search_askAssistant, { query: '' }))).toBeNull();
      expect(
        screen.queryByText(interpolate(TR_MAP.search_askAssistantAbout, { query: '' })),
      ).toBeNull();
    });

    it('debounces to exactly one request for a term typed one character at a time', async () => {
      vi.useFakeTimers();
      mockSearch.mockReturnValueOnce(Effect.succeed([]));
      setup();

      let value = '';
      for (const ch of 'alpha') {
        value += ch;
        await typeQuery(value);
        await settle(50); // well under the 250ms debounce — each keystroke resets the timer
      }
      await settle(250);

      expect(mockSearch).toHaveBeenCalledTimes(1);
      const call = mockSearch.mock.calls[0]?.[0];
      expect(call.query).toEqual({ q: 'alpha' });
    });

    it('shows the loading state while the request is in flight', async () => {
      vi.useFakeTimers();
      mockSearch.mockReturnValueOnce(Effect.never);
      setup();
      await typeQuery('ab');
      await settle();

      expect(screen.getByText(TR_MAP.search_loading)).not.toBeNull();
    });

    it('zero results renders the no-matches copy AND the Ask row', async () => {
      vi.useFakeTimers();
      mockSearch.mockReturnValueOnce(Effect.succeed([]));
      setup();
      await typeQuery('zzz');
      await settle();

      await waitFor(
        () => {
          expect(
            screen.getByText(interpolate(TR_MAP.search_noResults, { query: 'zzz' })),
          ).not.toBeNull();
        },
        { timeout: 2000, interval: 50 },
      );
      expect(
        screen.getByText(interpolate(TR_MAP.search_askAssistantAbout, { query: 'zzz' })),
      ).not.toBeNull();
    });

    it('offline: no request is issued, the offline copy renders, and the Ask row is hidden', async () => {
      vi.useFakeTimers();
      const onLineSpy = vi.spyOn(window.navigator, 'onLine', 'get').mockReturnValue(false);
      try {
        setup();
        await typeQuery('alpha');
        await settle();

        expect(mockSearch).not.toHaveBeenCalled();
        expect(screen.getByText(TR_MAP.error_offline)).not.toBeNull();
        expect(
          screen.queryByText(interpolate(TR_MAP.search_askAssistant, { query: 'alpha' })),
        ).toBeNull();
        expect(
          screen.queryByText(interpolate(TR_MAP.search_askAssistantAbout, { query: 'alpha' })),
        ).toBeNull();
      } finally {
        onLineSpy.mockRestore();
      }
    });

    it('a rejected request renders the error copy, keeps the dialog open, and still shows the Ask row', async () => {
      vi.useFakeTimers();
      mockSearch.mockReturnValueOnce(Effect.fail(new Error('boom')));
      setup();
      await typeQuery('alpha');
      await settle();

      await waitFor(() => {
        expect(screen.getByText(TR_MAP.search_error)).not.toBeNull();
      });
      expect(screen.getByRole('dialog')).not.toBeNull();
      expect(
        screen.getByText(interpolate(TR_MAP.search_askAssistantAbout, { query: 'alpha' })),
      ).not.toBeNull();
    });
  });

  describe('results and grouping (F.6/11-13, permissions §7)', () => {
    it('renders all five plural group headings and a row per kind, with no raw search_/assistant_ key ever in the DOM', async () => {
      vi.useFakeTimers();
      const hits = hitsThroughWire([
        eventHit({ title: 'Tuesday training' }),
        memberHit({ displayName: 'Jan Novák' }),
        groupHit({ name: 'U20' }),
        rosterHit({ name: 'First team' }),
        trainingTypeHit({ name: 'Speed' }),
      ]);
      mockSearch.mockReturnValueOnce(Effect.succeed(hits));
      const { container } = setup();
      // Two characters, not one: the dedicated floor test above pins that a 1-char query
      // issues no request at all, so a 1-char query here could never produce these rows.
      await typeQuery('ev');
      await settle();

      await waitFor(() => {
        expect(screen.getByText('Tuesday training')).not.toBeNull();
      });

      for (const heading of [
        TR_MAP.event_events,
        TR_MAP.team_members,
        TR_MAP.team_groups,
        TR_MAP.team_rosters,
        TR_MAP.team_trainingTypes,
      ]) {
        expect(screen.getByText(heading)).not.toBeNull();
      }
      expect(screen.getByText('Jan Novák')).not.toBeNull();
      expect(screen.getByText('U20')).not.toBeNull();
      expect(screen.getByText('First team')).not.toBeNull();
      expect(screen.getByText('Speed')).not.toBeNull();

      expect(container.textContent).not.toMatch(/\bsearch_[a-zA-Z]+\b/);
      expect(container.textContent).not.toMatch(/\bassistant_[a-zA-Z]+\b/);
    });

    it('a result set with no group hits renders no "Groups" heading, and no visible count appears anywhere (partial results read as normal, design §7)', async () => {
      vi.useFakeTimers();
      const hits = hitsThroughWire([eventHit({ title: 'Only an event' })]);
      mockSearch.mockReturnValueOnce(Effect.succeed(hits));
      setup();
      await typeQuery('only');
      await settle();

      await waitFor(() => {
        expect(screen.getByText('Only an event')).not.toBeNull();
      });

      expect(screen.queryByText(TR_MAP.team_groups)).toBeNull();
      expect(screen.queryByText(TR_MAP.team_members)).toBeNull();
      expect(screen.queryByText(TR_MAP.team_rosters)).toBeNull();
      expect(screen.queryByText(TR_MAP.team_trainingTypes)).toBeNull();

      // The heading that IS present carries no parenthetical/appended count — the sr-only
      // resultCount lives only in the live region, asserted separately below.
      expect(screen.getByText(TR_MAP.event_events).textContent).toBe(TR_MAP.event_events);

      // No visible (non-`aria-live`) count string anywhere in the dialog.
      const liveRegion = document.querySelector('[aria-live]');
      const dialog = screen.getByRole('dialog');
      const visibleNodes = Array.from(dialog.querySelectorAll('*')).filter(
        (el) => el !== liveRegion && !(liveRegion?.contains(el) ?? false),
      );
      for (const node of visibleNodes) {
        const ownText = Array.from(node.childNodes)
          .filter((n) => n.nodeType === Node.TEXT_NODE)
          .map((n) => n.textContent ?? '')
          .join('');
        expect(ownText).not.toMatch(/\d+\s*(results?|of\s+\d+)/i);
      }
    });

    it('shouldFilter={false} guard: a hit still renders even though cmdk would score its explicit value={kind:id}, not the visible text, against the query', async () => {
      vi.useFakeTimers();
      // The row's own PRIMARY text is made identical to the query, which would matter only if
      // cmdk were scoring rendered text — proving the row survives regardless demonstrates that
      // scoring is not happening against text at all (it is disabled via `shouldFilter`), since
      // the item's cmdk `value` is `member:<uuid>`, which never contains "Nováková".
      const hits = hitsThroughWire([memberHit({ displayName: 'Nováková' })]);
      mockSearch.mockReturnValueOnce(Effect.succeed(hits));
      setup();
      await typeQuery('Nováková');
      await settle();

      await waitFor(() => {
        expect(screen.getByText('Nováková')).not.toBeNull();
      });
    });
  });

  describe('keyboard selection (F.6/14-15)', () => {
    // The Ask row is always an item once something is typed, so a single hit means two
    // items, not one — ArrowDown moves onto the Ask row rather than wrapping. Enter with
    // no ArrowDown is what selects the hit, and that is the behaviour worth pinning.
    it('Enter selects the first hit', async () => {
      vi.useFakeTimers();
      const hit = eventHit({ title: 'The only hit' });
      mockSearch.mockReturnValueOnce(Effect.succeed(hitsThroughWire([hit])));
      const { onSelectHit, onOpenChange } = setup();
      await typeQuery('only');
      await settle();

      await waitFor(() => {
        expect(screen.getByText('The only hit')).not.toBeNull();
      });

      // No ArrowDown: with results on screen the top hit must already be the highlighted
      // item. If cmdk leaves the highlight on the Ask row (which is the only item while the
      // query is still being typed), a blind Enter fires an LLM turn instead of opening the
      // top result — the exact thing putting the Ask row last is meant to prevent.
      const input = getInput();
      fireEvent.keyDown(input, { key: 'Enter' });

      expect(onSelectHit).toHaveBeenCalledTimes(1);
      expect(onSelectHit.mock.calls[0]?.[0]).toEqual(hitsThroughWire([hit])[0]);
      // Selecting a hit must also close the dialog — the parent's `onOpenChange(false)`, not
      // just `onSelectHit`.
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    const kindCases: ReadonlyArray<{
      kind: string;
      build: () => AiChatApi.SearchHit;
      label: string;
    }> = [
      {
        kind: 'event',
        build: () => eventHit({ title: 'Select-me event' }),
        label: 'Select-me event',
      },
      {
        kind: 'member',
        build: () => memberHit({ displayName: 'Select-me member' }),
        label: 'Select-me member',
      },
      {
        kind: 'group',
        build: () => groupHit({ name: 'Select-me group' }),
        label: 'Select-me group',
      },
      {
        kind: 'roster',
        build: () => rosterHit({ name: 'Select-me roster' }),
        label: 'Select-me roster',
      },
      {
        kind: 'trainingType',
        build: () => trainingTypeHit({ name: 'Select-me tt' }),
        label: 'Select-me tt',
      },
    ];

    for (const { kind, build, label } of kindCases) {
      it(`selecting a ${kind} row calls onSelectHit with exactly that hit`, async () => {
        vi.useFakeTimers();
        const hit = build();
        const wired = hitsThroughWire([hit])[0];
        mockSearch.mockReturnValueOnce(Effect.succeed([wired]));
        const { onSelectHit } = setup();
        await typeQuery('select');
        await settle();

        const row = await waitFor(() => screen.getByText(label));
        const option = row.closest('[role="option"]');
        expect(option).not.toBeNull();
        // biome-ignore lint/style/noNonNullAssertion: asserted non-null above
        fireEvent.click(option!);

        expect(onSelectHit).toHaveBeenCalledTimes(1);
        expect(onSelectHit.mock.calls[0]?.[0]).toEqual(wired);
      });
    }

    // Regression: backspacing a results set all the way back to idle, then typing a fresh,
    // unrelated term, must not leave the highlight (and therefore a blind Enter) pinned on a
    // hit id from the earlier result set that is no longer even rendered.
    it('backspacing a result set down to idle and then typing a new term highlights the NEW first hit, not a stale one', async () => {
      vi.useFakeTimers();
      const firstHit = eventHit({ title: 'First-term hit' });
      const secondHit = eventHit({ title: 'Second-term hit' });
      mockSearch.mockReturnValueOnce(Effect.succeed(hitsThroughWire([firstHit])));
      const { onSelectHit } = setup();

      await typeQuery('items');
      await settle();
      await waitFor(() => {
        expect(screen.getByText('First-term hit')).not.toBeNull();
      });

      // Backspace all the way down to idle (below the 2-char floor) — no rows, no request.
      await typeQuery('i');
      await settle();
      expect(screen.getByText(TR_MAP.search_hint)).not.toBeNull();
      expect(screen.queryByText('First-term hit')).toBeNull();

      mockSearch.mockReturnValueOnce(Effect.succeed(hitsThroughWire([secondHit])));
      await typeQuery('other');
      await settle();
      await waitFor(() => {
        expect(screen.getByText('Second-term hit')).not.toBeNull();
      });

      const input = getInput();
      fireEvent.keyDown(input, { key: 'Enter' });

      expect(onSelectHit).toHaveBeenCalledTimes(1);
      expect(onSelectHit.mock.calls[0]?.[0]).toEqual(hitsThroughWire([secondHit])[0]);
    });
  });

  describe('the Ask row (F.6/16-17)', () => {
    it('selecting the Ask row calls onAskAssistant with the trimmed query', async () => {
      vi.useFakeTimers();
      mockSearch.mockReturnValueOnce(Effect.succeed([]));
      const { onAskAssistant, onOpenChange } = setup();
      await typeQuery('alpha');
      await settle();

      const label = await waitFor(() =>
        screen.getByText(interpolate(TR_MAP.search_askAssistantAbout, { query: 'alpha' })),
      );
      const option = label.closest('[role="option"]');
      expect(option).not.toBeNull();
      // biome-ignore lint/style/noNonNullAssertion: asserted non-null above
      fireEvent.click(option!);

      expect(onAskAssistant).toHaveBeenCalledWith('alpha');
      // Asking must also close the dialog, same as selecting a hit.
      expect(onOpenChange).toHaveBeenCalledWith(false);
    });

    it('a question-shaped query ("?" or >=4 words) uses search_askAssistant, not the "about" phrasing', async () => {
      vi.useFakeTimers();
      setup();
      await typeQuery('who is on the roster?');
      await settle();

      expect(
        screen.getByText(
          interpolate(TR_MAP.search_askAssistant, { query: 'who is on the roster?' }),
        ),
      ).not.toBeNull();
      expect(
        screen.queryByText(
          interpolate(TR_MAP.search_askAssistantAbout, { query: 'who is on the roster?' }),
        ),
      ).toBeNull();
    });

    it('a short name-like query (1-3 words, no "?") uses search_askAssistantAbout', async () => {
      vi.useFakeTimers();
      setup();
      await typeQuery('Novák');
      await settle();

      expect(
        screen.getByText(interpolate(TR_MAP.search_askAssistantAbout, { query: 'Novák' })),
      ).not.toBeNull();
      expect(
        screen.queryByText(interpolate(TR_MAP.search_askAssistant, { query: 'Novák' })),
      ).toBeNull();
    });
  });

  describe('reopen resets both query and debounced state (F.6/20, design §3.5)', () => {
    it('closing and reopening clears the input and renders no stale rows — even within the 250ms debounce window', async () => {
      vi.useFakeTimers();
      const hits = hitsThroughWire([eventHit({ title: 'Stale event' })]);
      mockSearch.mockReturnValueOnce(Effect.succeed(hits));
      const { rerenderWith } = setup({ open: true });

      await typeQuery('stale');
      await settle();
      await waitFor(() => {
        expect(screen.getByText('Stale event')).not.toBeNull();
      });

      rerenderWith({ open: false });
      rerenderWith({ open: true });

      // Immediately on reopen — well before the 250ms debounce could re-settle — there must be
      // no stale row and an empty input. Resetting only `query` (not `debounced`) would still
      // serve "stale" from the React Query cache for up to 250ms; this assertion is taken with
      // NO further timer advance, so it fails under that bug.
      expect(getInput().value).toBe('');
      expect(screen.queryByText('Stale event')).toBeNull();
      expect(screen.getByText(TR_MAP.search_hint)).not.toBeNull();
    });

    // The bug this pins: `placeholderData: (previous) => previous` is keyed per-observer, not
    // per-open-cycle, so the previous session's rows would render under an unrelated new term
    // with NO loading indicator (design §3.5) — and would still be clickable for a full
    // navigation. Reopening resets `query`/`debounced` (covered above), but that alone does not
    // stop `placeholderData` from re-serving the old rows once a new (unrelated) debounced value
    // lands — only a placeholderData that checks the previous/next query are related (a
    // prefix of one another) does.
    it("reopening and typing a brand-new, unrelated term shows loading — not the previous session's stale row", async () => {
      vi.useFakeTimers();
      const hits = hitsThroughWire([eventHit({ title: 'Stale event' })]);
      mockSearch.mockReturnValueOnce(Effect.succeed(hits));
      const { rerenderWith } = setup({ open: true });

      await typeQuery('stale');
      await settle();
      await waitFor(() => {
        expect(screen.getByText('Stale event')).not.toBeNull();
      });

      rerenderWith({ open: false });
      rerenderWith({ open: true });

      mockSearch.mockReturnValueOnce(Effect.never);
      await typeQuery('brandnew');
      await settle();

      expect(screen.queryByText('Stale event')).toBeNull();
      expect(screen.getByText(TR_MAP.search_loading)).not.toBeNull();
    });
  });

  describe('the 100-character input ceiling (F.6/22)', () => {
    it("the input carries maxLength=100, matching the server's `q` bound", () => {
      setup();
      expect(getInput().maxLength).toBe(100);
    });
  });

  describe('accessibility (F.6/23, design §8)', () => {
    it('has exactly one aria-live region, which is a sibling of the listbox (never nested inside it), and no role="status" anywhere in the dialog', async () => {
      vi.useFakeTimers();
      const hits = hitsThroughWire([eventHit({ title: 'A11y event' })]);
      mockSearch.mockReturnValueOnce(Effect.succeed(hits));
      setup();
      await typeQuery('a11y');
      await settle();

      await waitFor(() => {
        expect(screen.getByText('A11y event')).not.toBeNull();
      });

      const dialog = screen.getByRole('dialog');
      const liveRegions = dialog.querySelectorAll('[aria-live]');
      expect(liveRegions).toHaveLength(1);

      const listbox = screen.getByRole('listbox');
      expect(listbox.contains(liveRegions[0] as Node)).toBe(false);

      expect(dialog.querySelectorAll('[role="status"]')).toHaveLength(0);
    });
  });
});
